# Regenerates src/styles/design.css from the Claude Design handoff:
#   python3 scripts/scope-design-css.py design/claude-design-2026-11/design src/styles/design.css
# Hand-written adjustments belong in src/styles/design-app.css, not in the generated file.
import re, sys
D = sys.argv[1]; OUT = sys.argv[2]

def parse(s):
    """Return list of (prelude, body_or_children, kind). kind: 'rule'|'block'|'at'."""
    items=[]; i=0; n=len(s)
    while i<n:
        while i<n and s[i] in ' \n\t\r': i+=1
        if i>=n: break
        if s.startswith('/*',i):
            j=s.index('*/',i)+2; i=j; continue
        j=i
        while j<n and s[j] not in '{;': j+=1
        pre=s[i:j].strip()
        if j>=n: break
        if s[j]==';':
            items.append((pre,None,'at')); i=j+1; continue
        # find matching brace
        depth=0; k=j
        while True:
            if s[k]=='{': depth+=1
            elif s[k]=='}':
                depth-=1
                if depth==0: break
            k+=1
        body=s[j+1:k]
        if pre.startswith('@media') or pre.startswith('@container') or pre.startswith('@supports'):
            items.append((pre,parse(body),'block'))
        else:
            items.append((pre,body,'rule'))
        i=k+1
    return items

SKIP_SEL = re.compile(r'^(html|body(\.site)?|\*|a|a:hover|button|input,select,textarea|::selection|#nav.*|\.snav.*|\.logo.*|\.burger.*|\.theme-btn.*|\.site-h.*|\.ubar.*|\.mnav.*|\.foot(-g|-b)?\b.*|body\[data-for="candidate"\] \[data-only="employer"\],body\[data-for="employer"\] \[data-only="candidate"\]|:root.*|\.t-light|\.t-dark)$')
keyframes=set()

def scope_sel(sel):
    sel=sel.strip()
    m=re.match(r'^body\[data-for="(\w+)"\]\s*(.*)$',sel)
    if m: return f'html[data-for="{m.group(1)}"] .ds {m.group(2)}'
    if sel.startswith('.t-dark '):
        return None  # handled separately
    return '.ds '+sel

def emit(items, dark_rules):
    out=[]
    for pre,body,kind in items:
        if kind=='at':
            if pre.startswith('@import'): continue
            out.append(pre+';'); continue
        if kind=='block':
            inner=emit(body,dark_rules)
            if inner.strip(): out.append(pre+'{'+inner+'}')
            continue
        if pre.startswith('@keyframes'):
            name=pre.split()[1]; keyframes.add(name)
            out.append(f'@keyframes ds-{name}{{{body}}}'); continue
        if pre.startswith('@property'):
            out.append(pre+'{'+body+'}'); continue
        sels=[x.strip() for x in pre.split(',')]
        # selector lists with commas inside :is() not present in these files
        if SKIP_SEL.match(pre.strip()): continue
        kept=[]
        for x in sels:
            if x.startswith('.t-dark '):
                dark_rules.append((x[len('.t-dark '):],body)); continue
            if SKIP_SEL.match(x): continue
            kept.append(scope_sel(x))
        if kept: out.append(','.join(kept)+'{'+body+'}')
    return '\n'.join(out)

css=[]
dark=[]
for f in ['uktl-system.css','uktl-landing.css','uktl-site.css']:
    css.append(f'/* ── from {f} ── */\n'+emit(parse(re.sub(r"@import url\([^)]*\);","",open(f'{D}/{f}').read())),dark))
page=open(f'{D}/Services.html').read()
inline=page[page.index('<style>')+7:page.index('</style>')]
css.append('/* ── shared inline <style> of the marketing pages ── */\n'+emit(parse(inline),dark))
text='\n'.join(css)
names=sorted(keyframes,key=len,reverse=True)
def fix_anim(m):
    v=m.group(2)
    for nme in names:
        v=re.sub(r'(?<![\w-])'+re.escape(nme)+r'(?![\w-])','ds-'+nme,v)
    return m.group(1)+v
text=re.sub(r'(animation(?:-name)?\s*:)([^;}]*)',fix_anim,text)
darkcss='\n'.join(f':root.t-dark .ds {s}{{{b}}}' for s,b in dark)
darkmedia='@media (prefers-color-scheme: dark){'+'\n'.join(f':root:not(.t-light) .ds {s}{{{b}}}' for s,b in dark)+'}'
header='''/* GENERATED by scripts/scope-design-css.py from design/claude-design-2026-11 (uktl-system/landing/site.css),
   scoped under .ds so the design classes cannot collide with the app.
   Keyframes are prefixed ds-. Theme/audience come from <html> (see lib/preferences.ts). */
.ds{container-type:inline-size;--display:var(--font-display);--body:var(--font-body);--mono:var(--font-mono)}
'''
open(OUT,'w').write(header+text+'\n'+darkcss+'\n'+darkmedia+'\n')
print(len(text), sorted(keyframes)[:40], dark)
